import React, { useEffect, useRef, useState } from 'react';
import { ScrollView, StatusBar, Text as NativeText, TextProps, StyleSheet, View, Pressable, TextInput, Switch, Modal, Platform, Alert } from 'react-native';
import { router, useLocalSearchParams } from 'expo-router';
import { getAccessibilityColors, useAccessibility } from '@/context/accessibility';
import * as Speech from 'expo-speech';
import { AppIcon, type AppIconName } from '@/components/app-icon';

const C = { bg: '#f3f6fb', blue: '#0649ce', ink: '#09264f', muted: '#506887', border: '#c7d6eb', pale: '#eaf1fc', green: '#087c49', white: '#fff' };
const card = { backgroundColor: C.white, borderColor: C.border, borderWidth: 1, borderRadius: 16, padding: 16, marginBottom: 12 } as const;
const title = { fontSize: 20, color: C.ink, fontWeight: '500' as const };
function AppText({ style, ...props }: TextProps) {
  const { appearance, textScale, spacing } = useAccessibility();
  const colors = getAccessibilityColors(appearance);
  const original = StyleSheet.flatten(style) ?? {};
  const gap = spacing === 'Amplo' ? 1.6 : spacing === 'Confortável' ? 1.3 : 1;
  const originalColor = original.color;
  const color = originalColor === C.ink || originalColor === '#09264f' ? colors.text
    : originalColor === C.muted || originalColor === '#506887' ? colors.muted
      : originalColor === C.blue || originalColor === '#0648ce' ? colors.blue
        : originalColor === C.green ? colors.green
          : originalColor ?? colors.text;
  const baseFontSize = typeof original.fontSize === 'number' ? original.fontSize : 14;
  const fontSize = baseFontSize * textScale / 100;
  return <NativeText {...props} style={[original, { color, fontSize, lineHeight: (typeof original.lineHeight === 'number' ? original.lineHeight : baseFontSize * 1.25) * textScale / 100 * gap, letterSpacing: (typeof original.letterSpacing === 'number' ? original.letterSpacing : 0) + (spacing === 'Amplo' ? 1 : spacing === 'Confortável' ? 0.4 : 0) }]} />;
}
function Header({ page }: { page?: string }) { const { appearance } = useAccessibility(); const colors = getAccessibilityColors(appearance); return <View style={{ height: 52, backgroundColor: colors.surface, borderBottomWidth: 1, borderColor: colors.border, flexDirection: 'row', alignItems: 'center', paddingHorizontal: 14, justifyContent: 'space-between' }}><AppText style={{ color: colors.blue, fontWeight: '800', fontSize: 20 }}>Aula<AppText style={{ color: colors.green }}>Mais</AppText></AppText><AppText style={{ color: colors.text, fontWeight: '700' }}>{page}</AppText><View style={{ flexDirection: 'row', gap: 18, alignItems: 'center' }}><AppIcon name="notification" color={colors.text} /><AppIcon name="menu" color={colors.text} /></View></View>; }
function Label({ children }: { children: React.ReactNode }) { const { appearance } = useAccessibility(); const colors = getAccessibilityColors(appearance); return <AppText style={{ color: colors.blue, fontWeight: '800', fontSize: 11, letterSpacing: .7, marginBottom: 5 }}>{children}</AppText>; }
function Card({ children, style = {} }: { children: React.ReactNode; style?: object }) { const { appearance } = useAccessibility(); const colors = getAccessibilityColors(appearance); return <View style={[card, { backgroundColor: colors.surface, borderColor: colors.border }, style]}>{children}</View>; }
function Heading({ children, right, onRight }: { children: string; right?: string; onRight?: () => void }) { return <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginVertical: 8 }}><AppText style={title}>{children}</AppText>{right && <AppText onPress={onRight} style={{ color: C.blue, fontWeight: '700' }}>{right}</AppText>}</View>; }
function Page({ children, page }: { children: React.ReactNode; page?: string }) { const { appearance } = useAccessibility(); const colors = getAccessibilityColors(appearance); return <View style={{ flex: 1, backgroundColor: colors.background }}><StatusBar barStyle={colors.statusBar} backgroundColor={colors.surface} /><Header page={page} /><ScrollView style={{ backgroundColor: colors.background }} contentContainerStyle={{ padding: 13, paddingBottom: 24 }}>{children}</ScrollView></View>; }
function Row({ icon, heading, sub, color = '#edf3fc', onPress }: { icon: AppIconName; heading: string; sub?: string; color?: string; onPress?: () => void }) { const { appearance } = useAccessibility(); const colors = getAccessibilityColors(appearance); return <Pressable onPress={onPress} style={{ flexDirection: 'row', alignItems: 'center', gap: 12, paddingVertical: 12, borderBottomWidth: 1, borderColor: colors.border }}><View style={{ width: 40, height: 40, borderRadius: 11, backgroundColor: appearance === 'Escuro' || appearance === 'Contraste máximo' ? colors.pale : color, alignItems: 'center', justifyContent: 'center' }}><AppIcon name={icon} color={colors.blue} /></View><View style={{ flex: 1 }}><AppText style={{ color: colors.text, fontWeight: '700', fontSize: 14 }}>{heading}</AppText>{sub && <AppText style={{ color: colors.muted, marginTop: 3, fontSize: 12 }}>{sub}</AppText>}</View><AppIcon name="chevron" color={colors.text} /></Pressable>; }
function Progress({ value }: { value: number }) { const { appearance } = useAccessibility(); const colors = getAccessibilityColors(appearance); return <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8, marginTop: 10 }}><View style={{ flex: 1, height: 6, borderRadius: 5, backgroundColor: colors.border }}><View style={{ width: `${value}%`, height: 6, borderRadius: 5, backgroundColor: colors.blue }} /></View><AppText style={{ color: colors.text, fontSize: 11, fontWeight: '700' }}>{value}%</AppText></View>; }

export function Home() { return <Page><View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginVertical: 8 }}><View><Label>TERÇA-FEIRA, 20 DE MAIO</Label><AppText style={{ fontSize: 24, color: C.ink }}>Olá, Ana!</AppText><AppText style={{ color: C.muted, marginTop: 4 }}>Pronta para continuar aprendendo?</AppText></View><View style={{ backgroundColor: '#1874d1', width: 52, height: 52, borderRadius: 28, alignItems: 'center', justifyContent: 'center' }}><AppText style={{ color: '#fff', fontWeight: '800' }}>AO</AppText></View></View><Card style={{ padding: 0, paddingHorizontal: 12 }}><Row icon="accessibility" heading="Acessibilidade" sub="Ajuste texto, contraste e áudio" onPress={() => router.navigate('/acessibilidade' as never)} /></Card><Label>AGENDA</Label><Heading>Próxima aula</Heading><Card><View style={{ flexDirection: 'row', gap: 12, alignItems: 'center' }}><View style={{ backgroundColor: C.blue, borderRadius: 10, padding: 10 }}><AppText style={{ color: '#fff', fontWeight: '800', fontSize: 17 }}>21</AppText><AppText style={{ color: '#fff', fontSize: 11 }}>MAI</AppText></View><View style={{ flex: 1 }}><AppText style={{ color: C.blue, fontSize: 11, fontWeight: '700' }}>Amanhã, 10:00</AppText><AppText style={{ color: C.ink, marginTop: 5 }}>Matemática</AppText><AppText style={{ color: C.muted }}>Árvore binária · Prof. Carlos Silva</AppText></View><AppIcon name="chevron" color={C.ink} /></View></Card><Heading>Acesso rápido</Heading><View style={{ flexDirection: 'row', gap: 10 }}><Card style={{ flex: 1 }}><AppIcon name="lessons" color={C.blue} /><AppText style={{ color: C.ink, fontWeight: '700' }}>Minhas Aulas</AppText><AppText style={{ color: C.muted, fontSize: 12, marginTop: 5 }}>Veja suas disciplinas</AppText></Card><Card style={{ flex: 1 }}><AppIcon name="play" color={C.blue} /><AppText style={{ color: C.ink, fontWeight: '700' }}>Conteúdos</AppText><AppText style={{ color: C.muted, fontSize: 12, marginTop: 5 }}>Áudios e materiais</AppText></Card></View><View style={{ flexDirection: 'row', gap: 10 }}><Card style={{ flex: 1 }}><AppIcon name="grid" color={C.blue} /><AppText style={{ color: C.ink, fontWeight: '700' }}>Quadro ao Vivo</AppText><AppText style={{ color: C.muted, fontSize: 12, marginTop: 5 }}>Capture e leia textos</AppText></Card><Card style={{ flex: 1 }}><AppIcon name="accessibility" color={C.blue} /><AppText style={{ color: C.ink, fontWeight: '700' }}>Acessibilidade</AppText><AppText style={{ color: C.muted, fontSize: 12, marginTop: 5 }}>Personalize sua experiência</AppText></Card></View><Card style={{ borderLeftWidth: 4, borderLeftColor: C.blue }}><Label>CONTINUE DE ONDE PAROU</Label><AppText style={{ color: C.ink, fontSize: 17 }}>Equações do 2º grau</AppText><AppText style={{ color: C.muted }}>Matemática · 65% concluído</AppText><Progress value={65} /></Card><Heading>Atividades pendentes</Heading><Card><Row icon="calendar" heading="Lista de exercícios 4" sub="Ciências · Entrega em 2 dias" color="#fff1d5" /></Card></Page>; }
const subjects = [{ name: 'Matemática', teacher: 'Prof. Carlos Silva', progress: 78, color: '#edf3fc' }, { name: 'Português', teacher: 'Profa. Ana Oliveira', progress: 100, color: '#ddf7ec' }, { name: 'Ciências', teacher: 'Prof. Pedro Santos', progress: 42, color: '#fff1d5' }, { name: 'História', teacher: 'Profa. Beatriz Lima', progress: 34, color: '#f1eaff' }];
export function Classes() { const { appearance, textScale } = useAccessibility(); const colors = getAccessibilityColors(appearance); const [filter, setFilter] = useState('Todas'); const [search, setSearch] = useState(''); const data = subjects.filter(x => x.name.toLowerCase().includes(search.toLowerCase()) && (filter !== 'Concluídas' || x.progress === 100) && (filter !== 'Em andamento' || x.progress < 100)); return <Page page="Aulas"><View style={{ flexDirection: 'row', alignItems: 'center', backgroundColor: colors.surface, borderColor: colors.border, borderWidth: 1, borderRadius: 13, marginBottom: 12, paddingLeft: 12 }}><AppIcon name="search" color={colors.muted} /><TextInput placeholder="Buscar disciplina ou professor..." placeholderTextColor={colors.muted} value={search} onChangeText={setSearch} style={{ flex: 1, color: colors.text, padding: 13, fontSize: 14 * textScale / 100 }} /></View><View style={{ flexDirection: 'row', gap: 7, marginBottom: 12 }}>{['Todas', 'Em andamento', 'Concluídas'].map(x => <AppText key={x} onPress={() => setFilter(x)} style={{ backgroundColor: filter === x ? colors.blue : colors.surface, color: filter === x ? colors.surface : colors.text, borderColor: colors.border, borderWidth: 1, borderRadius: 22, paddingHorizontal: 13, paddingVertical: 9, fontWeight: '700' }}>{x}</AppText>)}</View><Heading>{`${data.length} disciplinas`}</Heading>{data.map(s => <Pressable key={s.name} accessibilityRole="button" accessibilityLabel={`Abrir aula de ${s.name}`} onPress={() => router.push({ pathname: '/disciplina', params: { subject: s.name } } as never)}><Card style={{ padding: 13 }}><View style={{ flexDirection: 'row', gap: 12, alignItems: 'center' }}><View style={{ width: 36, height: 36, backgroundColor: appearance === 'Escuro' || appearance === 'Contraste máximo' ? colors.pale : s.color, borderRadius: 10, alignItems: 'center', justifyContent: 'center' }}><AppIcon name="lessons" color={colors.blue} /></View><View style={{ flex: 1 }}><AppText style={{ color: colors.text, fontWeight: '700' }}>{s.name}</AppText><AppText style={{ color: colors.muted, fontSize: 12, marginTop: 5 }}>{s.teacher}</AppText><Progress value={s.progress} /></View><AppIcon name="chevron" color={colors.text} /></View><AppText style={{ position: 'absolute', right: 36, top: 12, color: s.progress === 100 ? colors.green : colors.blue, fontSize: 11, fontWeight: '700' }}>{s.progress === 100 ? '✓ Concluída' : 'Em andamento'}</AppText></Card></Pressable>)}</Page>; }
export function Accessibility() {
  const { textScale, setTextScale, spacing, setSpacing, appearance, setAppearance, reduceMotion, setReduceMotion, voice, setVoice, readingSpeed, setReadingSpeed } = useAccessibility();
  const [spacingOpen, setSpacingOpen] = useState(false);
  const [speedOpen, setSpeedOpen] = useState(false);
  const colors = getAccessibilityColors(appearance);
  const optionModal = (visible: boolean, heading: string, options: string[], selected: string, setter: (value: string) => void, close: (value: boolean) => void) => <Modal visible={visible} transparent animationType={reduceMotion ? 'none' : 'fade'} onRequestClose={() => close(false)}><Pressable onPress={() => close(false)} style={{ flex: 1, backgroundColor: '#0008', justifyContent: 'center', padding: 24 }}><Pressable onPress={() => { }} style={{ backgroundColor: colors.surface, borderRadius: 18, padding: 20, borderWidth: appearance === 'Alto contraste' || appearance === 'Contraste máximo' ? 2 : 1, borderColor: colors.border }}><AppText style={{ color: colors.text, fontSize: 20, fontWeight: '700', marginBottom: 12 }}>{heading}</AppText>{options.map(option => <Pressable key={option} accessibilityRole="radio" accessibilityState={{ checked: selected === option }} onPress={() => { setter(option); close(false); }} style={{ paddingVertical: 14, borderBottomWidth: 1, borderColor: colors.border, flexDirection: 'row', justifyContent: 'space-between' }}><AppText style={{ color: colors.text, fontSize: 16 }}>{option}</AppText>{selected === option ? <AppIcon name="check" color={colors.blue} /> : null}</Pressable>)}<Pressable onPress={() => close(false)} style={{ alignSelf: 'flex-end', paddingTop: 16 }}><AppText style={{ color: colors.blue, fontWeight: '700' }}>Fechar</AppText></Pressable></Pressable></Pressable></Modal>;
  return <Page page="Acessibilidade"><View style={{ backgroundColor: colors.background, margin: -13, padding: 13, gap: 12 }}>
    <AppText style={{ fontSize: 24, color: colors.text, marginBottom: 5 }}>Personalize sua experiência</AppText><AppText style={{ color: colors.muted, lineHeight: 21, marginBottom: 4 }}>As alterações são aplicadas imediatamente em todas as abas.</AppText>
    <Card style={{ padding: 0 }}><View style={{ padding: 14, borderBottomWidth: 1, borderColor: colors.border }}><AppText style={[title, { color: colors.text }]}>Aa  Texto</AppText><AppText style={{ color: colors.muted }}>Tamanho e espaçamento</AppText><View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', marginTop: 14 }}><Pressable accessibilityLabel="Diminuir tamanho do texto" onPress={() => setTextScale(v => Math.max(100, v - 10))} style={{ borderWidth: 1, borderColor: colors.blue, borderRadius: 12, padding: 10 }}><AppText style={{ color: colors.blue, fontWeight: '700' }}>A− Diminuir</AppText></Pressable><AppText style={{ color: colors.text, backgroundColor: colors.background, padding: 10, fontWeight: '700' }}>{textScale}%</AppText><Pressable accessibilityLabel="Aumentar tamanho do texto" onPress={() => setTextScale(v => Math.min(200, v + 10))} style={{ borderWidth: 1, borderColor: colors.blue, borderRadius: 12, padding: 10 }}><AppText style={{ color: colors.blue, fontWeight: '700' }}>A+ Aumentar</AppText></Pressable></View><View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: 5, marginTop: 12 }}>{Array.from({ length: 10 }, (_, i) => (i + 11) * 10).map(size => <Pressable key={size} onPress={() => setTextScale(size)} style={{ paddingHorizontal: 9, paddingVertical: 7, borderRadius: 9, borderWidth: 1, borderColor: textScale === size ? colors.blue : colors.border, backgroundColor: textScale === size ? colors.pale : colors.surface }}><AppText style={{ color: colors.text, fontSize: 12 }}>{size}%</AppText></Pressable>)}</View></View>
      <Row icon="text" heading="Espaçamento do texto" sub={`Atual: ${spacing}`} onPress={() => setSpacingOpen(true)} /><View style={{ padding: 12, backgroundColor: colors.pale, borderRadius: 12, margin: 12 }}><Label>PRÉ-VISUALIZAÇÃO</Label><AppText style={{ color: colors.text, fontSize: 15, lineHeight: 20 }}>Aprender transforma o mundo. Este texto mostra como ficará a leitura.</AppText></View></Card>
    <Card style={{ padding: 0 }}><View style={{ padding: 14, borderBottomWidth: 1, borderColor: colors.border }}><View style={{ flexDirection: 'row', alignItems: 'center', gap: 8 }}><AppIcon name="accessibility" color={colors.text} /><AppText style={[title, { color: colors.text }]}>Aparência</AppText></View><AppText style={{ color: colors.muted }}>Cores e movimento</AppText></View><View style={{ padding: 12, flexDirection: 'row', flexWrap: 'wrap', gap: 8 }}>{['Claro', 'Escuro', 'Alto contraste', 'Contraste máximo'].map(x => <Pressable key={x} accessibilityRole="radio" accessibilityState={{ checked: appearance === x }} onPress={() => setAppearance(x as typeof appearance)} style={{ width: '48%', padding: 13, borderWidth: appearance === x && (x === 'Alto contraste' || x === 'Contraste máximo') ? 2 : 1, borderColor: appearance === x ? colors.blue : colors.border, borderRadius: 12, flexDirection: 'row', alignItems: 'center', gap: 7 }}><AppIcon name={appearance === x ? 'checkCircle' : 'accessibility'} size={17} color={appearance === x ? colors.blue : colors.muted} /><AppText style={{ color: colors.text, fontWeight: '700' }}>{x}</AppText></Pressable>)}</View><View style={{ padding: 14, borderTopWidth: 1, borderColor: colors.border, flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between' }}><View><AppText style={{ color: colors.text, fontWeight: '700' }}>Reduzir animações</AppText><AppText style={{ color: colors.muted, fontSize: 12 }}>{reduceMotion ? 'Animações reduzidas' : 'Animações no ritmo normal'}</AppText></View><Switch value={reduceMotion} onValueChange={setReduceMotion} accessibilityLabel="Reduzir animações" trackColor={{ true: colors.green }} /></View></Card>
    <Card style={{ padding: 0 }}><View style={{ padding: 14, borderBottomWidth: 1, borderColor: colors.border }}><View style={{ flexDirection: 'row', alignItems: 'center', gap: 8 }}><AppIcon name="sound" color={colors.text} /><AppText style={[title, { color: colors.text }]}>Áudio</AppText></View><AppText style={{ color: colors.muted }}>Leitura por voz</AppText></View><View style={{ padding: 14, flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center' }}><View><AppText style={{ color: colors.text, fontWeight: '700' }}>Leitura por voz</AppText><AppText style={{ color: colors.muted }}>Ouça conteúdos e controles</AppText></View><Switch value={voice} onValueChange={setVoice} trackColor={{ true: colors.green }} /></View><Pressable accessibilityRole="button" onPress={() => setSpeedOpen(true)} style={{ padding: 14, borderTopWidth: 1, borderColor: colors.border, flexDirection: 'row', justifyContent: 'space-between' }}><AppText style={{ color: colors.text, fontWeight: '700' }}>Velocidade de leitura</AppText><View style={{ flexDirection: 'row', alignItems: 'center', gap: 5 }}><AppText style={{ color: colors.blue }}>{readingSpeed}</AppText><AppIcon name="chevron" color={colors.blue} /></View></Pressable></Card>
    <Pressable onPress={() => { setTextScale(100); setSpacing('Normal'); setReadingSpeed('1x'); setVoice(true); setReduceMotion(false); setAppearance('Claro'); }} style={{ borderWidth: 1, borderColor: colors.blue, borderRadius: 12, padding: 14 }}><View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: 8 }}><AppIcon name="arrowBack" color={colors.blue} /><AppText style={{ color: colors.blue, fontWeight: '700' }}>Restaurar configurações padrão</AppText></View></Pressable>
    {optionModal(spacingOpen, 'Espaçamento do texto', ['Normal', 'Confortável', 'Amplo'], spacing, value => setSpacing(value as typeof spacing), setSpacingOpen)}{optionModal(speedOpen, 'Velocidade de leitura', ['0,75x', '1x', '1,25x', '1,5x'], readingSpeed, setReadingSpeed, setSpeedOpen)}
  </View></Page>;
}
export function Profile() { const { profileInfo } = useAccessibility(); const initials = profileInfo.fullName.split(/\s+/).map(part => part[0]).slice(0, 2).join('').toUpperCase(); return <Page page="Perfil"><View style={{ flexDirection: 'row', alignItems: 'center', gap: 14, marginVertical: 10 }}><View style={{ backgroundColor: '#1874d1', width: 78, height: 78, borderRadius: 40, alignItems: 'center', justifyContent: 'center', borderWidth: 3, borderColor: '#fff' }}><AppText style={{ color: '#fff', fontWeight: '800', fontSize: 22 }}>{initials}</AppText></View><View><AppText style={{ color: C.ink, fontSize: 25 }}>{profileInfo.fullName}</AppText><AppText style={{ color: C.muted }}>Estudante · 2º ano</AppText><View style={{ flexDirection: 'row', alignItems: 'center', gap: 4, marginTop: 5 }}><AppIcon name="checkCircle" size={15} color={C.green} /><AppText style={{ color: C.green, fontWeight: '700' }}>Conta verificada</AppText></View></View></View><Card><Label>INFORMAÇÕES ACADÊMICAS</Label><View style={{ flexDirection: 'row', flexWrap: 'wrap' }}>{[['Matrícula', '202500123'], ['Turma', '2º Ano B'], ['Escola', 'Colégio Horizonte'], ['Turno', 'Manhã']].map(([k, v]) => <View key={k} style={{ width: '50%', paddingVertical: 7 }}><AppText style={{ color: C.muted, fontSize: 12 }}>{k}</AppText><AppText style={{ color: C.ink, fontWeight: '700', marginTop: 4 }}>{v}</AppText></View>)}</View></Card><Heading right="Ver detalhes">Progresso acadêmico</Heading><Card><View style={{ flexDirection: 'row', gap: 14, alignItems: 'center' }}><View style={{ width: 76, height: 76, borderRadius: 40, borderWidth: 7, borderColor: C.green, alignItems: 'center', justifyContent: 'center' }}><AppText style={{ color: C.ink, fontSize: 18, fontWeight: '800' }}>72%</AppText><AppText style={{ color: C.muted, fontSize: 9 }}>concluído</AppText></View><View style={{ flex: 1 }}><AppText style={{ color: C.ink, fontWeight: '700' }}>Ótimo progresso!</AppText><AppText style={{ color: C.muted, lineHeight: 23, marginTop: 5 }}>Você concluiu 18 de 25 atividades neste período.</AppText></View></View></Card><Card style={{ paddingHorizontal: 12 }}><Row icon="person" heading="Informações pessoais" sub="Nome, contato e dados acadêmicos" onPress={() => router.push('/informacoes-pessoais' as never)} /><Row icon="notification" heading="Notificações" sub="Preferências e horários de silêncio" onPress={() => router.push('/notificacoes' as never)} /><Row icon="lock" heading="Senha e segurança" sub="Proteja o acesso à sua conta" /><Row icon="privacy" heading="Privacidade" sub="Controle seus dados pessoais" /></Card><Pressable accessibilityRole="button" style={{ borderWidth: 1, borderColor: '#eb3737', borderRadius: 12, padding: 13, flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: 7 }}><AppIcon name="signOut" color="#c21f1f" /><AppText style={{ color: '#c21f1f', fontWeight: '700' }}>Sair da conta</AppText></Pressable><View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: 6, marginTop: 14 }}><AppIcon name="privacy" size={14} color={C.muted} /><AppText style={{ color: C.muted, fontSize: 12 }}>Seus dados são protegidos e nunca serão exibidos sem sua autorização.</AppText></View></Page>; }
export function Notifications() {
  const { appearance, textScale, notificationPreferences, setNotificationPreferences, profileInfo } = useAccessibility();
  const colors = getAccessibilityColors(appearance);
  const [draft, setDraft] = useState(notificationPreferences);
  const [saved, setSaved] = useState(false);
  const update = <K extends keyof typeof draft,>(key: K, value: (typeof draft)[K]) => { setDraft(current => ({ ...current, [key]: value })); setSaved(false); };
  const inputStyle = { flex: 1, minWidth: 0, minHeight: 44, backgroundColor: colors.surface, color: colors.text, borderWidth: 1, borderColor: colors.border, borderRadius: 9, paddingHorizontal: 10, fontSize: 14 * textScale / 100, fontWeight: '700' as const };
  const notificationRow = (key: 'newLessons' | 'deadlines' | 'achievements' | 'schoolAnnouncements' | 'push' | 'email', icon: AppIconName, heading: string, description: string) => <View key={key} style={{ minHeight: 76, paddingHorizontal: 14, paddingVertical: 10, borderTopWidth: 1, borderColor: colors.border, flexDirection: 'row', alignItems: 'center', gap: 11 }}><View style={{ width: 38, height: 38, borderRadius: 10, backgroundColor: colors.pale, alignItems: 'center', justifyContent: 'center' }}><AppIcon name={icon} color={colors.blue} /></View><View style={{ flex: 1 }}><AppText style={{ color: colors.text, fontWeight: '700', fontSize: 14 }}>{heading}</AppText><AppText style={{ color: colors.muted, fontSize: 12, lineHeight: 17 }}>{description}</AppText></View><Switch value={draft[key]} onValueChange={value => update(key, value)} accessibilityLabel={heading} trackColor={{ false: colors.border, true: colors.green }} thumbColor="#ffffff" /></View>;

  return <View style={{ flex: 1, backgroundColor: colors.background }}><StatusBar barStyle={colors.statusBar} backgroundColor={colors.surface}/>
    <View style={{ height: 52, flexDirection: 'row', alignItems: 'center', gap: 13, backgroundColor: colors.surface, borderBottomWidth: 1, borderColor: colors.border, paddingHorizontal: 14 }}><Pressable onPress={() => router.back()} accessibilityRole="button" accessibilityLabel="Voltar ao perfil"><AppIcon name="arrowBack" color={colors.text} size={21} /></Pressable><AppText style={{ color: colors.text, fontSize: 17, fontWeight: '700' }}>Notificações</AppText></View>
    <ScrollView style={{ backgroundColor: colors.background }} contentContainerStyle={{ padding: 12, paddingBottom: 20 }}>
      <AppText style={{ color: colors.text, fontSize: 25, marginBottom: 2 }}>Preferências</AppText><AppText style={{ color: colors.muted, fontSize: 14, marginBottom: 14 }}>Escolha quais avisos deseja receber e por onde.</AppText>
      <Card style={{ padding: 0, overflow: 'hidden' }}><View style={{ padding: 14, flexDirection: 'row', alignItems: 'center', gap: 11 }}><AppIcon name="notification" color={colors.text} /><View><AppText style={{ color: colors.text, fontSize: 20 }}>O que você quer receber</AppText><AppText style={{ color: colors.muted, fontSize: 12 }}>Avisos importantes do AulaMais</AppText></View></View>
        {notificationRow('newLessons', 'lessons', 'Novas aulas', 'Quando novos conteúdos estiverem disponíveis')}
        {notificationRow('deadlines', 'calendar', 'Atividades e prazos', 'Lembretes antes da data de entrega')}
        {notificationRow('achievements', 'sparkle', 'Conquistas', 'Celebrações de progresso e metas')}
        {notificationRow('schoolAnnouncements', 'notification', 'Comunicados da escola', 'Informações importantes da instituição')}
      </Card>
      <Card style={{ padding: 0, overflow: 'hidden' }}><View style={{ padding: 14, flexDirection: 'row', alignItems: 'center', gap: 11 }}><AppIcon name="email" color={colors.text} /><View><AppText style={{ color: colors.text, fontSize: 20 }}>Canais</AppText><AppText style={{ color: colors.muted, fontSize: 12 }}>Como você quer receber</AppText></View></View>
        {notificationRow('push', 'notification', 'Notificação no aplicativo', 'Avisos na tela do seu dispositivo')}
        {notificationRow('email', 'email', 'E-mail', `Resumo enviado para ${profileInfo.email}`)}
      </Card>
      <Card style={{ padding: 0, overflow: 'hidden' }}><View style={{ padding: 14, borderBottomWidth: 1, borderColor: colors.border, flexDirection: 'row', alignItems: 'center', gap: 11 }}><AppIcon name="clock" color={colors.text} /><View><AppText style={{ color: colors.text, fontSize: 20 }}>Horário de silêncio</AppText><AppText style={{ color: colors.muted, fontSize: 12 }}>Nenhum aviso durante este período</AppText></View></View><View style={{ padding: 14 }}><View style={{ flexDirection: 'row', alignItems: 'flex-end', gap: 8 }}><View style={{ flex: 1 }}><AppText style={{ color: colors.text, fontWeight: '700', marginBottom: 7 }}>De</AppText><TextInput accessibilityLabel="Início do horário de silêncio" value={draft.quietFrom} onChangeText={value => update('quietFrom', value)} placeholder="22:00" placeholderTextColor={colors.muted} keyboardType="numbers-and-punctuation" style={inputStyle}/></View><AppText style={{ color: colors.muted, paddingBottom: 12 }}>até</AppText><View style={{ flex: 1 }}><AppText style={{ color: colors.text, fontWeight: '700', marginBottom: 7 }}>Até</AppText><TextInput accessibilityLabel="Fim do horário de silêncio" value={draft.quietUntil} onChangeText={value => update('quietUntil', value)} placeholder="07:00" placeholderTextColor={colors.muted} keyboardType="numbers-and-punctuation" style={inputStyle}/></View></View><AppText style={{ color: colors.muted, fontSize: 12, marginTop: 12 }}>Avisos urgentes da escola ainda poderão ser enviados.</AppText></View></Card>
      <Pressable onPress={() => { setNotificationPreferences(draft); setSaved(true); }} accessibilityRole="button" style={{ minHeight: 47, borderRadius: 10, backgroundColor: colors.blue, alignItems: 'center', justifyContent: 'center', marginBottom: 8 }}><View style={{ flexDirection: 'row', alignItems: 'center', gap: 8 }}><AppIcon name="save" color={appearance === 'Contraste máximo' ? '#000' : '#fff'} /><AppText style={{ color: appearance === 'Contraste máximo' ? '#000' : '#fff', fontWeight: '700' }}>Salvar preferências</AppText></View></Pressable>
      {saved ? <AppText style={{ color: colors.green, textAlign: 'center', fontWeight: '700' }}>Preferências salvas.</AppText> : null}
    </ScrollView>
  </View>;
}

export function PersonalInformation() {
  const { appearance, textScale, profileInfo, setProfileInfo } = useAccessibility();
  const colors = getAccessibilityColors(appearance);
  const [form, setForm] = useState(profileInfo);
  const [message, setMessage] = useState('');
  const field = (key: keyof typeof form, value: string) => { setForm(current => ({ ...current, [key]: value })); setMessage(''); };
  const inputStyle = { flex: 1, minHeight: 46, backgroundColor: colors.surface, color: colors.text, borderColor: colors.border, borderWidth: 1, borderRadius: 10, paddingHorizontal: 12, paddingVertical: 10, fontSize: 14 * textScale / 100 } as const;
  const labelStyle = { color: colors.text, fontSize: 14, fontWeight: '700' as const, marginBottom: 7 };
  const save = () => {
    if (!form.fullName.trim() || !form.birthDate.trim() || !form.email.trim()) { setMessage('Preencha o nome, a data de nascimento e o e-mail.'); return; }
    setProfileInfo(form);
    setMessage('Suas alterações foram salvas.');
  };

  return <View style={{ flex: 1, backgroundColor: colors.background }}><StatusBar barStyle={colors.statusBar} backgroundColor={colors.surface}/>
    <View style={{ height: 52, flexDirection: 'row', alignItems: 'center', gap: 13, backgroundColor: colors.surface, borderBottomWidth: 1, borderColor: colors.border, paddingHorizontal: 14 }}><Pressable onPress={() => router.back()} accessibilityRole="button" accessibilityLabel="Voltar ao perfil"><AppIcon name="arrowBack" color={colors.text} size={21} /></Pressable><AppText style={{ color: colors.text, fontSize: 17, fontWeight: '700' }}>Informações pessoais</AppText></View>
    <ScrollView style={{ backgroundColor: colors.background }} contentContainerStyle={{ padding: 12, paddingBottom: 20 }}>
      <AppText style={{ color: colors.text, fontSize: 25, marginBottom: 2 }}>Seus dados</AppText><AppText style={{ color: colors.muted, fontSize: 14 }}>Mantenha suas informações atualizadas.</AppText><AppText style={{ color: colors.muted, fontSize: 14, marginBottom: 14 }}>Campos com * são obrigatórios.</AppText>
      <Card style={{ padding: 0, borderRadius: 16 }}>
        <View style={{ padding: 16, gap: 14 }}><AppText style={{ color: colors.text, fontSize: 20, marginBottom: 1 }}>Dados básicos</AppText>
          <View><AppText style={labelStyle}>Nome completo *</AppText><TextInput accessibilityLabel="Nome completo" value={form.fullName} onChangeText={value => field('fullName', value)} placeholder="Nome completo" placeholderTextColor={colors.muted} style={inputStyle} /></View>
          <View><AppText style={labelStyle}>Data de nascimento *</AppText><View style={{ flexDirection: 'row', alignItems: 'center', gap: 8 }}><TextInput accessibilityLabel="Data de nascimento" value={form.birthDate} onChangeText={value => field('birthDate', value)} placeholder="DD/MM/AAAA" placeholderTextColor={colors.muted} keyboardType="numbers-and-punctuation" style={inputStyle} /><AppIcon name="calendar" color={colors.text} size={18} /></View></View>
          <View><AppText style={labelStyle}>CPF</AppText><TextInput accessibilityLabel="CPF" value={form.cpf} editable={false} selectTextOnFocus={false} style={[inputStyle, { backgroundColor: colors.pale, color: colors.muted }]} /><AppText style={{ color: colors.muted, fontSize: 12, fontWeight: '600', marginTop: 6 }}>Este dado não pode ser alterado pelo aplicativo.</AppText></View>
        </View>
        <View style={{ borderTopWidth: 1, borderColor: colors.border, padding: 16, gap: 14 }}><AppText style={{ color: colors.text, fontSize: 20, marginBottom: 1 }}>Contato</AppText>
          <View><AppText style={labelStyle}>E-mail *</AppText><TextInput accessibilityLabel="E-mail" value={form.email} onChangeText={value => field('email', value)} placeholder="seu@email.com" placeholderTextColor={colors.muted} keyboardType="email-address" autoCapitalize="none" style={inputStyle} /></View>
          <View><AppText style={labelStyle}>Telefone</AppText><TextInput accessibilityLabel="Telefone" value={form.phone} onChangeText={value => field('phone', value)} placeholder="(00) 00000-0000" placeholderTextColor={colors.muted} keyboardType="phone-pad" style={inputStyle} /></View>
        </View>
        <View style={{ paddingHorizontal: 16, paddingTop: 2 }}><View style={{ backgroundColor: appearance === 'Claro' ? '#fff2d6' : colors.pale, borderRadius: 12, padding: 13, flexDirection: 'row', gap: 10 }}><AppIcon name="privacy" color={appearance === 'Claro' ? '#96600a' : colors.blue} /><View style={{ flex: 1 }}><AppText style={{ color: appearance === 'Claro' ? '#855208' : colors.text, fontWeight: '700' }}>Seus dados estão seguros</AppText><AppText style={{ color: appearance === 'Claro' ? '#855208' : colors.muted, fontSize: 14, lineHeight: 21 }}>Usamos apenas as informações necessárias para oferecer o serviço.</AppText></View></View></View>
        <View style={{ padding: 16, gap: 12 }}><Pressable onPress={save} accessibilityRole="button" style={{ minHeight: 46, borderRadius: 10, backgroundColor: colors.blue, alignItems: 'center', justifyContent: 'center' }}><View style={{ flexDirection: 'row', alignItems: 'center', gap: 8 }}><AppIcon name="save" color={appearance === 'Contraste máximo' ? '#000' : '#fff'} /><AppText style={{ color: appearance === 'Contraste máximo' ? '#000' : '#fff', fontWeight: '700' }}>Salvar alterações</AppText></View></Pressable><Pressable onPress={() => { setForm(profileInfo); setMessage(''); router.back(); }} accessibilityRole="button" style={{ alignItems: 'center', paddingVertical: 5 }}><AppText style={{ color: colors.blue, fontWeight: '700' }}>Cancelar</AppText></Pressable>{message ? <AppText accessibilityRole="alert" style={{ color: message.startsWith('Preencha') ? '#c21f1f' : colors.green, textAlign: 'center', fontWeight: '600' }}>{message}</AppText> : null}</View>
      </Card>
    </ScrollView>
  </View>;
}

const lessonBySubject: Record<string, { title: string; teacher: string; date: string; duration: number; intro: string; description: string; transcript: string }> = {
  Matemática: { title: 'Árvore Binária', teacher: 'Prof. Carlos Silva', date: '12/05/2025', duration: 165, intro: 'O que é uma árvore binária?', description: 'Uma árvore binária é uma estrutura de dados em que cada elemento pode possuir no máximo dois filhos: o filho esquerdo e o filho direito.', transcript: 'Uma árvore binária é uma estrutura em que cada nó pode possuir, no máximo, dois filhos.\n\nEsses elementos são chamados de filho esquerdo e filho direito.' },
  Português: { title: 'Interpretação de Texto', teacher: 'Profa. Ana Oliveira', date: '14/05/2025', duration: 180, intro: 'Como compreender um texto?', description: 'Interpretar um texto é identificar suas ideias, relacionar informações e perceber o que o autor quer comunicar.', transcript: 'Para interpretar um texto, observe o tema, as ideias principais e as relações entre os parágrafos.\n\nLeia com atenção e use o contexto para compreender palavras e expressões.' },
  Ciências: { title: 'Ciclo da Água', teacher: 'Prof. Pedro Santos', date: '16/05/2025', duration: 155, intro: 'Como a água circula na natureza?', description: 'O ciclo da água reúne os processos de evaporação, condensação e precipitação que movimentam a água pelo planeta.', transcript: 'O calor do Sol provoca a evaporação da água. O vapor sobe, esfria e se condensa em nuvens.\n\nQuando as gotas ficam pesadas, a água retorna à superfície em forma de chuva.' },
  História: { title: 'Brasil Colônia', teacher: 'Profa. Beatriz Lima', date: '19/05/2025', duration: 190, intro: 'Como começou a colonização?', description: 'A colonização portuguesa transformou a organização política, econômica e social do território que hoje chamamos Brasil.', transcript: 'A chegada dos portugueses em 1500 iniciou um longo período de colonização.\n\nA produção de açúcar e a exploração do território marcaram os primeiros séculos desse processo.' },
};
type LessonTab = 'Conteúdo' | 'Quadro' | 'Anotações';
const lessonTabs: LessonTab[] = ['Conteúdo', 'Quadro', 'Anotações'];
const readingSpeeds = ['0,75x', '1x', '1,25x', '1,5x'];
function formatTime(seconds: number) { return `${Math.floor(seconds / 60).toString().padStart(2, '0')}:${Math.floor(seconds % 60).toString().padStart(2, '0')}`; }

function TreeDiagram({ large = false }: { large?: boolean }) {
  return <View style={{ width: large ? 320 : '100%', maxWidth: 320, alignSelf: 'center', height: large ? 220 : 190, backgroundColor: '#edf3fc', borderColor: '#d2def1', borderWidth: 1, borderRadius: 14, paddingTop: 8, alignItems: 'center' }}>
    <View style={{ width: 260, height: 140, position: 'relative' }}>
      <View style={[treeEdge, { left: 54, top: 47, transform: [{ rotate: '-36deg' }] }]} /><View style={[treeEdge, { left: 124, top: 47, transform: [{ rotate: '36deg' }] }]} />
      <View style={[treeEdge, { left: 20, top: 95, transform: [{ rotate: '-56deg' }] }]} /><View style={[treeEdge, { left: 48, top: 95, transform: [{ rotate: '56deg' }] }]} /><View style={[treeEdge, { left: 150, top: 95, transform: [{ rotate: '-56deg' }] }]} /><View style={[treeEdge, { left: 178, top: 95, transform: [{ rotate: '56deg' }] }]} />
      <View style={{ position: 'absolute', left: 115, top: 1 }}><Node value="8" /></View><View style={{ position: 'absolute', left: 50, top: 49 }}><Node value="4" /></View><View style={{ position: 'absolute', left: 180, top: 49 }}><Node value="12" /></View>
      <View style={{ position: 'absolute', left: 15, top: 105 }}><Node value="2" /></View><View style={{ position: 'absolute', left: 80, top: 105 }}><Node value="6" /></View><View style={{ position: 'absolute', left: 145, top: 105 }}><Node value="10" /></View><View style={{ position: 'absolute', left: 210, top: 105 }}><Node value="14" /></View>
    </View><AppText style={{ color: C.blue, fontWeight: '700', fontSize: 11 }}>Toque para ampliar</AppText>
  </View>;
}
function Node({ value }: { value: string }) { return <View style={{ width: 30, height: 30, borderRadius: 15, borderWidth: 1.5, borderColor: C.blue, backgroundColor: '#fff', alignItems: 'center', justifyContent: 'center' }}><AppText style={{ color: C.ink, fontSize: 13, fontWeight: '700' }}>{value}</AppText></View>; }
const treeEdge = { position: 'absolute' as const, width: 82, height: 1.5, backgroundColor: '#6e829f' };

export function Subject() {
  const { subject } = useLocalSearchParams<{ subject: string }>();
  const course = subject || 'Matemática';
  const lesson = lessonBySubject[course] ?? lessonBySubject.Matemática;
  const { appearance, reduceMotion, readingSpeed, setReadingSpeed, voice } = useAccessibility();
  const colors = getAccessibilityColors(appearance);
  const [tab, setTab] = useState<LessonTab>('Conteúdo');
  const [expandedDiagram, setExpandedDiagram] = useState(false);
  const [playing, setPlaying] = useState(false);
  const [elapsed, setElapsed] = useState(24);
  const [largeTranscript, setLargeTranscript] = useState(false);
  const [notes, setNotes] = useState('');
  const speechText = `${lesson.intro}. ${lesson.description} ${lesson.transcript}`;
  const boundaryRef = useRef(Math.round(24 / lesson.duration * speechText.length));
  useEffect(() => () => { void Speech.stop(); }, []);
  useEffect(() => { if (!voice && playing) void Speech.stop(); }, [voice, playing]);

  const speakFrom = (startIndex: number, selectedSpeed = readingSpeed) => {
    const rate = Number(selectedSpeed.replace('x', '').replace(',', '.')) || 1;
    Speech.speak(speechText.slice(startIndex), {
      language: 'pt-BR', rate,
      onStart: () => setPlaying(true),
      onBoundary: (event: { charIndex: number }) => {
        const position = Math.min(speechText.length, startIndex + event.charIndex);
        boundaryRef.current = position;
        setElapsed(Math.floor(position / speechText.length * lesson.duration));
      },
      onDone: () => { boundaryRef.current = 0; setElapsed(lesson.duration); setPlaying(false); },
      onStopped: () => setPlaying(false),
      onError: () => setPlaying(false),
    });
  };
  const togglePlayback = async () => {
    if (playing) {
      if (Platform.OS === 'ios' || Platform.OS === 'web') await Speech.pause();
      else await Speech.stop();
      setPlaying(false);
      return;
    }
    if (!voice) { Alert.alert('Leitura por voz desativada', 'Ative a leitura por voz na aba Acessibilidade para ouvir este conteúdo.'); return; }
    if (elapsed >= lesson.duration) { boundaryRef.current = 0; setElapsed(0); }
    const startIndex = elapsed >= lesson.duration ? 0 : boundaryRef.current;
    await Speech.stop();
    speakFrom(startIndex);
  };

  const changeTime = async (delta: number) => {
    const nextElapsed = Math.max(0, Math.min(lesson.duration, elapsed + delta));
    const wasPlaying = playing;
    const nextBoundary = Math.round(nextElapsed / lesson.duration * speechText.length);
    boundaryRef.current = nextBoundary;
    setElapsed(nextElapsed);
    if (wasPlaying) { await Speech.stop(); if (voice) speakFrom(nextBoundary); }
  };
  const cycleSpeed = async () => {
    const nextSpeed = readingSpeeds[(readingSpeeds.indexOf(readingSpeed) + 1) % readingSpeeds.length];
    setReadingSpeed(nextSpeed);
    if (playing) { const position = boundaryRef.current; await Speech.stop(); speakFrom(position, nextSpeed); }
  };
  const tabContent = tab === 'Conteúdo' ? <>
    <Card style={{ padding: 16, borderRadius: 17 }}><AppText style={{ color: colors.text, fontSize: 21, marginBottom: 14 }}>Resumo da aula</AppText><AppText style={{ color: colors.text, fontWeight: '500', fontSize: 16, marginBottom: 6 }}>{lesson.intro}</AppText><AppText style={{ color: colors.muted, fontSize: 15, lineHeight: 23 }}>{lesson.description}</AppText>{course === 'Matemática' && <Pressable accessibilityRole="button" accessibilityLabel="Ampliar diagrama da árvore binária" onPress={() => setExpandedDiagram(true)} style={{ marginTop: 14 }}><TreeDiagram /></Pressable>}</Card>
    <View style={{ backgroundColor: '#102b55', borderRadius: 16, padding: 16, marginBottom: 12 }}><View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between' }}><View style={{ flexDirection: 'row', alignItems: 'center', gap: 7 }}><AppIcon name="sound" color="#fff" /><AppText style={{ color: '#fff', fontWeight: '700', fontSize: 15 }}>Ouvir conteúdo</AppText></View><Pressable onPress={cycleSpeed} accessibilityRole="button" accessibilityLabel={`Velocidade ${readingSpeed}`} style={{ borderWidth: 1, borderColor: '#9bb2d4', borderRadius: 9, paddingHorizontal: 11, paddingVertical: 7 }}><AppText style={{ color: '#fff', fontWeight: '700', fontSize: 13 }}>{readingSpeed}</AppText></Pressable></View><View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: 22, marginVertical: 13 }}><Pressable onPress={() => { void changeTime(-15); }} accessibilityLabel="Voltar 15 segundos" style={playerCircle}><AppIcon name="rewind" color="#fff" size={20} /></Pressable><Pressable onPress={() => { void togglePlayback(); }} accessibilityRole="button" accessibilityLabel={playing ? 'Pausar conteúdo' : 'Reproduzir conteúdo'} style={[playerCircle, { width: 52, height: 52, backgroundColor: '#f4f7fc', borderColor: '#f4f7fc' }]}><AppIcon name={playing ? 'pause' : 'play'} color="#102b55" size={23} /></Pressable><Pressable onPress={() => { void changeTime(15); }} accessibilityLabel="Avançar 15 segundos" style={playerCircle}><AppIcon name="forward" color="#fff" size={20} /></Pressable></View><View style={{ flexDirection: 'row', alignItems: 'center', gap: 10 }}><View style={{ height: 6, flex: 1, backgroundColor: '#526985', borderRadius: 4, overflow: 'hidden' }}><View style={{ width: `${elapsed / lesson.duration * 100}%`, height: '100%', backgroundColor: '#1762e8' }} /></View><AppText style={{ color: '#fff', fontSize: 12 }}>{formatTime(elapsed)} / {formatTime(lesson.duration)}</AppText></View></View>
    <Card style={{ padding: 16, borderRadius: 17 }}><View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12 }}><AppText style={{ color: colors.text, fontSize: 20 }}>Transcrição</AppText><Pressable onPress={() => setLargeTranscript(value => !value)}><AppText style={{ color: colors.blue, fontWeight: '700', fontSize: 14 }}>{largeTranscript ? 'Texto normal' : 'Texto maior'}</AppText></Pressable></View><AppText style={{ color: colors.text, fontSize: largeTranscript ? 19 : 15, lineHeight: largeTranscript ? 29 : 23, paddingHorizontal: 10 }}>{lesson.transcript}</AppText></Card>
  </> : tab === 'Quadro' ? <Card style={{ padding: 18, minHeight: 390, borderRadius: 17 }}><AppText style={{ color: colors.text, fontSize: 21, marginBottom: 6 }}>Quadro da aula</AppText><AppText style={{ color: colors.muted, marginBottom: 14 }}>Acompanhe os pontos principais da explicação.</AppText><View style={{ flex: 1, minHeight: 280, borderWidth: 1, borderColor: colors.border, borderRadius: 12, backgroundColor: colors.surface, padding: 18 }}><AppText style={{ color: colors.blue, fontSize: 18, fontWeight: '700', textAlign: 'center' }}>{lesson.title}</AppText><View style={{ height: 1, backgroundColor: colors.border, marginVertical: 14 }} /><AppText style={{ color: colors.text, fontSize: 16, lineHeight: 25 }}>{lesson.description}</AppText>{course === 'Matemática' && <View style={{ marginTop: 20 }}><TreeDiagram /></View>}</View></Card> : <Card style={{ padding: 18, minHeight: 360, borderRadius: 17 }}><AppText style={{ color: colors.text, fontSize: 21, marginBottom: 6 }}>Minhas anotações</AppText><AppText style={{ color: colors.muted, marginBottom: 14 }}>Suas anotações ficam disponíveis enquanto esta aula estiver aberta.</AppText><TextInput multiline textAlignVertical="top" value={notes} onChangeText={setNotes} placeholder="Escreva suas anotações aqui..." placeholderTextColor={colors.muted} style={{ minHeight: 260, borderWidth: 1, borderColor: colors.border, borderRadius: 12, padding: 14, color: colors.text, backgroundColor: colors.surface, fontSize: 16, lineHeight: 24 }} /></Card>;

  return <View style={{ flex: 1, backgroundColor: colors.background }}><StatusBar barStyle={colors.statusBar} backgroundColor={colors.surface} /><View style={{ height: 48, flexDirection: 'row', alignItems: 'center', gap: 12, backgroundColor: colors.surface, borderBottomWidth: 1, borderColor: colors.border, paddingHorizontal: 16 }}><Pressable onPress={() => router.back()} accessibilityRole="button" accessibilityLabel="Voltar para aulas"><AppIcon name="arrowBack" color={colors.text} size={21} /></Pressable><AppText style={{ color: colors.text, fontSize: 18, fontWeight: '700' }}>Detalhes</AppText></View>
    <ScrollView style={{ flex: 1, backgroundColor: colors.background }} contentContainerStyle={{ padding: 12, paddingBottom: 18 }}><View style={{ flexDirection: 'row', alignItems: 'center', gap: 12, paddingHorizontal: 4, paddingVertical: 9 }}><View style={{ width: 38, height: 38, borderRadius: 11, backgroundColor: colors.pale, alignItems: 'center', justifyContent: 'center' }}><AppIcon name="lessons" color={colors.blue} /></View><View style={{ flex: 1 }}><View style={{ alignSelf: 'flex-start', borderWidth: 1, borderColor: colors.green, borderRadius: 15, paddingHorizontal: 10, paddingVertical: 3, marginBottom: 4 }}><AppText style={{ color: colors.green, fontSize: 11, fontWeight: '700' }}>{course === 'Matemática' || course === 'Português' ? '✓ Concluída' : 'Em andamento'}</AppText></View><AppText style={{ color: colors.text, fontSize: 25, fontWeight: '500' }}>{lesson.title}</AppText><AppText style={{ color: colors.muted, fontSize: 14, marginTop: 2 }}>{course} · {lesson.teacher}</AppText><View style={{ flexDirection: 'row', alignItems: 'center', gap: 5, marginTop: 6 }}><AppIcon name="calendar" color={colors.muted} size={14} /><AppText style={{ color: colors.muted, fontSize: 12, fontWeight: '600' }}>{lesson.date}</AppText><AppIcon name="clock" color={colors.muted} size={14} /><AppText style={{ color: colors.muted, fontSize: 12, fontWeight: '600' }}>10:00</AppText></View></View></View>
      <View style={{ flexDirection: 'row', borderBottomWidth: 1, borderColor: colors.border, marginTop: 6, marginBottom: 14 }}>{lessonTabs.map(item => <Pressable key={item} accessibilityRole="tab" accessibilityState={{ selected: tab === item }} onPress={() => setTab(item)} style={{ flex: 1, alignItems: 'center', paddingVertical: 13, borderBottomWidth: tab === item ? 3 : 0, borderColor: colors.blue }}><AppText style={{ color: tab === item ? colors.blue : colors.muted, fontWeight: '700', fontSize: 14 }}>{item}</AppText></Pressable>)}</View>
      {tabContent}
    </ScrollView>
    <Modal visible={expandedDiagram} transparent animationType={reduceMotion ? 'none' : 'fade'} onRequestClose={() => setExpandedDiagram(false)}><Pressable onPress={() => setExpandedDiagram(false)} style={{ flex: 1, backgroundColor: '#0009', alignItems: 'center', justifyContent: 'center', padding: 20 }}><Pressable onPress={() => { }} style={{ backgroundColor: colors.surface, borderRadius: 18, padding: 20, width: '100%', maxWidth: 360 }}><AppText style={{ color: colors.text, fontSize: 20, fontWeight: '700', marginBottom: 18 }}>Árvore binária</AppText><TreeDiagram large /><Pressable onPress={() => setExpandedDiagram(false)} style={{ alignSelf: 'flex-end', paddingTop: 16 }}><AppText style={{ color: colors.blue, fontWeight: '700' }}>Fechar</AppText></Pressable></Pressable></Pressable></Modal>
  </View>;
}

const playerCircle = { width: 42, height: 42, borderRadius: 22, borderWidth: 1, borderColor: '#9bb2d4', alignItems: 'center' as const, justifyContent: 'center' as const };

